//#region src/bridge/agent-session-cli.ts
const args = process.argv.slice(2);
const helperRelease = globalThis.__AGENTGIS_HELPER_RELEASE__;
if (args.includes("--version")) {
	console.log(JSON.stringify({
		service: "agentgis-local-agent-session",
		application_version: "0.8.0",
		bridge_protocol: 4,
		...helperRelease ? { helper_version: helperRelease.version } : {}
	}));
	process.exit(0);
}
if (args.includes("--help")) {
	console.log("AgentGIS official Local Agent Session: --machine [--port 47831] [--origin https://agent-gis.7m7s.tech] [--timeout-ms 120000] [--max-upload-mb 32768] | --mcp-stdio [same flags] | --version");
	process.exit(0);
}
const port = numberFlag("--port", 47831);
const timeoutMs = numberFlag("--timeout-ms", 12e4, 1e3, 18e5);
const maxUploadMb = numberFlag("--max-upload-mb", 32768, 1, 1048576);
const origins = repeatedFlag("--origin");
const machine = args.includes("--machine");
const allowedOrigins = origins.length > 0 ? origins : [
	"https://agent-gis.7m7s.tech",
	"http://127.0.0.1:5173",
	"http://localhost:5173"
];
if (args.includes("--mcp-stdio")) {
	const stdio = createAgentGisStdioServer({
		port,
		allowedOrigins,
		commandTimeoutMs: timeoutMs,
		maxBrowserUploadBytes: maxUploadMb * 1024 * 1024,
		...helperRelease ? { helperVersion: helperRelease.version } : {}
	});
	const stop = async () => {
		await stdio.close();
		process.exit(0);
	};
	process.once("SIGINT", () => void stop());
	process.once("SIGTERM", () => void stop());
	process.stdin.once("end", () => void stop());
	await stdio.server.connect(new StdioServerTransport());
} else await runMachineOrInteractive();
async function runMachineOrInteractive() {
	const session = await startLocalAgentSession({
		port,
		allowedOrigins,
		commandTimeoutMs: timeoutMs,
		maxBrowserUploadBytes: maxUploadMb * 1024 * 1024
	});
	if (machine) console.log(JSON.stringify({
		ok: true,
		...helperRelease ? { helper_version: helperRelease.version } : {},
		service: "agentgis-local-agent-session",
		session_file: session.sessionFile,
		bridge_session_id: session.descriptor.bridge_session_id,
		host: session.descriptor.host,
		port: session.descriptor.port
	}));
	else {
		console.log("AgentGIS Local Agent Session");
		console.log(`Session File: ${session.sessionFile}`);
		console.log(`Bridge Session: ${session.descriptor.bridge_session_id}`);
		console.log(`Health: ${session.descriptor.health_url}`);
		console.log(`Allowed Browser Origins: ${allowedOrigins.join(", ")}`);
		console.log(`Browser upload limit: ${maxUploadMb} MiB`);
		console.log("Local bearer credentials are stored only in the private session file (mode 0600). Do not paste its contents into chat or logs.");
	}
	let shuttingDown = false;
	const shutdown = async () => {
		if (shuttingDown) return;
		shuttingDown = true;
		await session.close();
		process.exit(0);
	};
	process.once("SIGINT", () => void shutdown());
	process.once("SIGTERM", () => void shutdown());
}
function repeatedFlag(name) {
	const values = [];
	for (let index = 0; index < args.length; index += 1) if (args[index] === name && args[index + 1]) {
		values.push(args[index + 1]);
		index += 1;
	}
	return values;
}
function numberFlag(name, fallback, min = 0, max = 65535) {
	const index = args.indexOf(name);
	if (index < 0 || !args[index + 1]) return fallback;
	const value = Number(args[index + 1]);
	if (!Number.isInteger(value) || value < min || value > max) throw new Error(`${name} must be an integer between ${min} and ${max}`);
	return value;
}
